#!/usr/bin/env python3
"""Generates the widget's progress-ring vector drawables (ring_p001..ring_p100 + ring_track).

Widgets can't draw arbitrary arcs, and bitmaps bloat widget updates, so each whole percent
gets its own tiny vector arc. They're drawn white and tinted with theme colors at runtime.
Run from the repo root: python3 tools/gen_rings.py
"""
import math
import os

OUT = "app/src/main/res/drawable"
SIZE, STROKE = 100, 11
R = (SIZE - STROKE) / 2
C = SIZE / 2

HEADER = """<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by tools/gen_rings.py. Do not edit. -->
<vector xmlns:android="http://schemas.android.com/apk/res/android"
    android:width="{s}dp" android:height="{s}dp"
    android:viewportWidth="{s}" android:viewportHeight="{s}">
""".format(s=SIZE)


def point(deg):
    rad = math.radians(deg)
    return C + R * math.sin(rad), C - R * math.cos(rad)


def path(d, cap="round"):
    return (f'    <path android:strokeColor="#FFFFFFFF" android:strokeWidth="{STROKE}"\n'
            f'        android:strokeLineCap="{cap}" android:pathData="{d}" />\n')


def write(name, body):
    with open(os.path.join(OUT, name), "w") as f:
        f.write(HEADER + body + "</vector>\n")


full = f"M{C},{C - R} A{R},{R} 0 1,1 {C},{C + R} A{R},{R} 0 1,1 {C},{C - R}"
write("ring_track.xml", path(full, cap="butt"))

for p in range(1, 101):
    if p == 100:
        d = full
    else:
        x, y = point(360 * p / 100)
        large = 1 if p > 50 else 0
        d = f"M{C},{C - R} A{R},{R} 0 {large},1 {x:.2f},{y:.2f}"
    write(f"ring_p{p:03d}.xml", path(d))

KT = "app/src/main/java/app/wakesteps/widget/RingDrawables.kt"
with open(KT, "w") as f:
    f.write("// Generated by tools/gen_rings.py. Do not edit.\n")
    f.write("package app.wakesteps.widget\n\nimport app.wakesteps.R\n\n")
    f.write("/** Index n (1..100) is an arc covering n% of the ring; index 0 is unused. */\n")
    f.write("internal val RING_ARCS = intArrayOf(\n    0,\n")
    for p in range(1, 101):
        f.write(f"    R.drawable.ring_p{p:03d},\n")
    f.write(")\n")
